svg.script:
var stages = [].slice.call(document.querySelectorAll(".panel-stage"));
var benefitItems = [].slice.call(document.querySelectorAll(".benefit-item"));
stages.forEach(function(stage, index) {
  function advance() {
    var next = stages[index + 1];
    if (!next || !next.classList.contains("panel-stage-hidden")) return;
    next.classList.remove("panel-stage-hidden");
    stage.setAttribute("aria-expanded", "true");
    if (next.id === "panel2") {
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        benefitItems.forEach(function(item) { item.classList.add("benefit-item-visible"); });
        next.classList.add("stamp-marked");
      } else {
        benefitItems.forEach(function(item, itemIndex) {
          var delay = itemIndex < 4 ? itemIndex * 250 : 1670 + (itemIndex - 4) * 250;
          window.setTimeout(function() {
            item.classList.add("benefit-item-visible");
          }, delay);
        });
        window.setTimeout(function() { next.classList.add("stamp-striking"); }, 3840);
        window.setTimeout(function() {
          next.classList.remove("stamp-striking");
          next.classList.add("stamp-marked");
        }, 5290);
      }
    }
    if (next.id === "panel3" && !window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      document.getElementById("heritage-star").classList.add("heritage-star-spin");
    }
  }
  stage.addEventListener("click", advance);
  stage.addEventListener("keydown", function(event) {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      advance();
    }
  });
});
